from uselemma_tracing.model import (
    pick_generation_model_identity,
    pick_model_identity,
)


def test_pick_model_identity_empty():
    assert pick_model_identity(None) is None
    assert pick_model_identity({}) is None
    assert pick_model_identity("") is None
    assert pick_model_identity("   ") is None
    assert pick_model_identity("gpt-4o") is None
    assert pick_model_identity("It arrives Friday.") is None


def test_pick_model_identity_aliases():
    assert pick_model_identity({"model": "gpt-4o"}) == "gpt-4o"
    assert pick_model_identity({"model_name": "gpt-4o-mini"}) == "gpt-4o-mini"
    assert pick_model_identity({"modelName": "claude-3"}) == "claude-3"
    assert pick_model_identity({"model_id": "o3"}) == "o3"
    assert pick_model_identity({"modelId": "gpt-4.1"}) == "gpt-4.1"
    assert pick_model_identity({"ls_model_name": "gpt-4o"}) == "gpt-4o"


def test_pick_model_identity_nested_response_metadata():
    assert (
        pick_model_identity({"response_metadata": {"model_name": "gpt-4o-mini"}})
        == "gpt-4o-mini"
    )
    assert (
        pick_model_identity({"model": {"modelId": "gpt-4o", "provider": "openai"}})
        == "gpt-4o"
    )


def test_pick_model_identity_ignores_message_response_and_text_strings():
    assert pick_model_identity({"message": "hello"}) is None
    assert pick_model_identity({"response": "hello"}) is None
    assert pick_model_identity({"text": "It arrives Friday."}) is None
    assert pick_model_identity({"role": "assistant", "content": "hello"}) is None


class _FakeAIMessage:
    def __init__(self, content: str, model_name: str) -> None:
        self.content = content
        self.type = "ai"
        self.response_metadata = {"model_name": model_name}


def test_pick_generation_model_identity_from_response_metadata():
    assert (
        pick_generation_model_identity(
            {
                "generations": [
                    [
                        {
                            "text": "hello",
                            "message": _FakeAIMessage("hello", "gpt-4o-mini"),
                        }
                    ]
                ]
            }
        )
        == "gpt-4o-mini"
    )


def test_pick_generation_model_identity_prefers_top_level():
    assert (
        pick_generation_model_identity(
            {
                "model": "gpt-4o",
                "generations": [
                    [{"message": {"response_metadata": {"model_name": "other"}}}]
                ],
            }
        )
        == "gpt-4o"
    )


def test_pick_generation_model_identity_ignores_text_and_string_messages():
    assert (
        pick_generation_model_identity(
            {"generations": [[{"text": "It arrives Friday.", "message": "hello"}]]}
        )
        is None
    )

/**
 * Drive openAIAgents() through the real OpenAI Agents SDK.
 * No network: local Model + mocked ingest.
 * Replaces the default OpenAI trace backend so CI never calls api.openai.com.
 */
import {
  Agent,
  run,
  setTraceProcessors,
  setTracingDisabled,
  Usage,
  withGenerationSpan,
  withTrace,
  type Model,
} from "@openai/agents";
import { afterEach, describe, expect, it } from "vitest";
import { ingestFetchMock, jsonBody, LEMMA_PROJECT_ID } from "../test-helpers";
import { openAIAgents } from "./openai-agents";

function scriptedModel(text: string): Model {
  return {
    name: "scripted",
    async getResponse() {
      // Custom models do not emit generation spans unless they open one.
      return withGenerationSpan(
        async () => ({
          usage: new Usage({
            requests: 1,
            inputTokens: 1,
            outputTokens: 1,
            totalTokens: 2,
          }),
          output: [
            {
              type: "message",
              role: "assistant",
              status: "completed",
              content: [{ type: "output_text", text }],
            },
          ],
        }),
        { data: { type: "generation", model: "scripted" } },
      );
    },
    async *getStreamedResponse() {},
  };
}

describe("openAIAgents through real Agents SDK", () => {
  afterEach(() => {
    setTraceProcessors([]);
    // Restore the SDK's NODE_ENV=test default.
    setTracingDisabled(true);
  });

  it("run() sends one owned trace", async () => {
    const fetchMock = ingestFetchMock();
    const processor = openAIAgents({
      apiKey: "key",
      projectId: LEMMA_PROJECT_ID,
      fetch: fetchMock as typeof fetch,
    });
    // The Agents SDK disables tracing when NODE_ENV=test (vitest).
    setTracingDisabled(false);
    setTraceProcessors([processor]);

    const agent = new Agent({
      name: "support-agent",
      instructions: "Be brief.",
      model: scriptedModel("hello from agents"),
    });

    const result = await withTrace(
      "support-agent",
      async () => run(agent, "hi"),
      {
        groupId: "thread-1",
        metadata: { userId: "user-1" },
      },
    );
    await processor.forceFlush();

    expect(String(result.finalOutput ?? "")).toContain("hello");
    expect(fetchMock).toHaveBeenCalledTimes(1);
    const trace = jsonBody(fetchMock.mock.calls[0]).trace;
    expect(trace).toMatchObject({
      name: "support-agent",
      thread_id: "thread-1",
      user_id: "user-1",
    });
    expect(
      trace.spans.some((span: { type: string }) => span.type === "generation"),
    ).toBe(true);
  });
});

import { describe, expect, it } from "vitest";
import {
  pickGenerationModelIdentity,
  pickModelIdentity,
} from "./model";

describe("pickModelIdentity", () => {
  it("returns undefined for empty payloads and bare strings", () => {
    expect(pickModelIdentity(undefined)).toBeUndefined();
    expect(pickModelIdentity(null)).toBeUndefined();
    expect(pickModelIdentity({})).toBeUndefined();
    expect(pickModelIdentity("")).toBeUndefined();
    expect(pickModelIdentity("   ")).toBeUndefined();
    expect(pickModelIdentity("gpt-4o")).toBeUndefined();
    expect(pickModelIdentity("It arrives Friday.")).toBeUndefined();
  });

  it("reads model aliases including ls_model_name", () => {
    expect(pickModelIdentity({ model: "gpt-4o" })).toBe("gpt-4o");
    expect(pickModelIdentity({ model_name: "gpt-4o-mini" })).toBe("gpt-4o-mini");
    expect(pickModelIdentity({ modelName: "claude-3" })).toBe("claude-3");
    expect(pickModelIdentity({ model_id: "o3" })).toBe("o3");
    expect(pickModelIdentity({ modelId: "gpt-4.1" })).toBe("gpt-4.1");
    expect(pickModelIdentity({ ls_model_name: "gpt-4o" })).toBe("gpt-4o");
  });

  it("reads nested response_metadata and model objects", () => {
    expect(
      pickModelIdentity({
        response_metadata: { model_name: "gpt-4o-mini" },
      }),
    ).toBe("gpt-4o-mini");
    expect(
      pickModelIdentity({
        model: { modelId: "gpt-4o", provider: "openai" },
      }),
    ).toBe("gpt-4o");
  });

  it("does not treat message/response/text strings as a model id", () => {
    expect(pickModelIdentity({ message: "hello" })).toBeUndefined();
    expect(pickModelIdentity({ response: "hello" })).toBeUndefined();
    expect(pickModelIdentity({ text: "It arrives Friday." })).toBeUndefined();
    expect(
      pickModelIdentity({ role: "assistant", content: "hello" }),
    ).toBeUndefined();
  });
});

describe("pickGenerationModelIdentity", () => {
  it("walks LangChain LLMResult generations for response_metadata.model_name", () => {
    expect(
      pickGenerationModelIdentity({
        generations: [
          [
            {
              text: "hello",
              message: {
                content: "hello",
                type: "ai",
                response_metadata: { model_name: "gpt-4o-mini" },
              },
            },
          ],
        ],
      }),
    ).toBe("gpt-4o-mini");
  });

  it("prefers a top-level model over nested generation metadata", () => {
    expect(
      pickGenerationModelIdentity({
        model: "gpt-4o",
        generations: [
          [{ message: { response_metadata: { model_name: "other" } } }],
        ],
      }),
    ).toBe("gpt-4o");
  });

  it("does not treat generation text or string messages as a model id", () => {
    expect(
      pickGenerationModelIdentity({
        generations: [[{ text: "It arrives Friday.", message: "hello" }]],
      }),
    ).toBeUndefined();
  });
});

import { describe, expect, it, vi } from "vitest";

import { Lemma } from "./client";
import {
  codingAgentTurnTrace,
  completeCodingAgentTurn,
  recordCodingAgentToolResult,
  recordCodingAgentToolStart,
  startCodingAgentTurn,
} from "./coding-agent";

function jsonBody(call: unknown[]) {
  return JSON.parse(String((call[1] as RequestInit).body)) as {
    trace: {
      id: string;
      thread_id: string;
      input: unknown;
      output: unknown;
      metadata: Record<string, unknown>;
      spans: Array<Record<string, unknown>>;
    };
  };
}

describe("coding-agent turn assembly", () => {
  it("builds two complete traces linked by one harness session", async () => {
    const fetchMock = vi.fn(async () => new Response("{}", { status: 201 }));
    const lemma = new Lemma({
      apiKey: "scoped-key",
      projectId: "10000000-0000-0000-0000-000000000001",
      baseUrl: "https://api.example.test",
      fetch: fetchMock as typeof fetch,
    });

    const first = completeCodingAgentTurn(
      recordCodingAgentToolResult(
        recordCodingAgentToolStart(
          startCodingAgentTurn({
            harness: "codex",
            sessionId: "session-1",
            turnId: "turn-1",
            traceId: "trace-1",
            generationId: "generation-1",
            prompt: "Inspect the repository",
            startedAt: "2026-08-19T10:00:00.000Z",
            model: "gpt-5",
          }),
          {
            toolUseId: "tool-1",
            toolName: "exec_command",
            input: { cmd: "rg --files" },
            startedAt: "2026-08-19T10:00:01.000Z",
          },
        ),
        {
          toolUseId: "tool-1",
          toolName: "exec_command",
          input: { cmd: "rg --files" },
          output: { output: "package.json" },
          endedAt: "2026-08-19T10:00:02.000Z",
        },
      ),
      {
        response: "I found the package manifest.",
        endedAt: "2026-08-19T10:00:03.000Z",
        generationStartedAt: "2026-08-19T10:00:02.000Z",
        generationEndedAt: "2026-08-19T10:00:03.000Z",
      },
    );
    const second = completeCodingAgentTurn(
      startCodingAgentTurn({
        harness: "codex",
        sessionId: "session-1",
        turnId: "turn-2",
        traceId: "trace-2",
        generationId: "generation-2",
        prompt: "Now explain it",
        startedAt: "2026-08-19T10:01:00.000Z",
      }),
      {
        response: "It is a TypeScript package.",
        endedAt: "2026-08-19T10:01:01.000Z",
      },
    );

    for (const turn of [first, second]) {
      const assembled = codingAgentTurnTrace(turn);
      await lemma.ingest(assembled.context, {
        startedAt: new Date(assembled.startedAt),
        endedAt: new Date(assembled.endedAt),
      });
    }

    const bodies = fetchMock.mock.calls.map(jsonBody);
    expect(bodies.map((body) => body.trace.id)).toEqual(["trace-1", "trace-2"]);
    expect(bodies.map((body) => body.trace.thread_id)).toEqual([
      "session-1",
      "session-1",
    ]);
    expect(bodies[0].trace).toMatchObject({
      input: "Inspect the repository",
      output: "I found the package manifest.",
      metadata: {
        "lemma.harness.id": "codex",
        "lemma.harness.session_id": "session-1",
        "lemma.harness.turn_id": "turn-1",
      },
    });
    expect(bodies[0].trace.spans).toEqual([
      expect.objectContaining({
        id: "tool-1",
        name: "exec_command",
        type: "tool",
        input: { cmd: "rg --files" },
        output: { output: "package.json" },
        tool_name: "exec_command",
        started_at: "2026-08-19T10:00:01.000Z",
        ended_at: "2026-08-19T10:00:02.000Z",
      }),
      expect.objectContaining({
        id: "generation-1",
        name: "codex response",
        type: "generation",
        model: "gpt-5",
        input: "Inspect the repository",
        output: "I found the package manifest.",
        started_at: "2026-08-19T10:00:02.000Z",
        ended_at: "2026-08-19T10:00:03.000Z",
      }),
    ]);
  });

  it("derives stable trace and generation ids from the turn identity", () => {
    const options = {
      harness: "codex" as const,
      sessionId: "session-1",
      turnId: "turn-1",
      prompt: "hello",
      startedAt: "2026-08-19T10:00:00.000Z",
    };

    const first = startCodingAgentTurn(options);
    const replay = startCodingAgentTurn(options);
    const nextTurn = startCodingAgentTurn({ ...options, turnId: "turn-2" });

    expect(replay.traceId).toBe(first.traceId);
    expect(replay.generationId).toBe(first.generationId);
    expect(nextTurn.traceId).not.toBe(first.traceId);
    expect(first.traceId).toMatch(
      /^[0-9a-f]{8}-[0-9a-f]{4}-5[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/,
    );
  });

  it("finalizes on the assistant response without a session-end event", () => {
    const completed = completeCodingAgentTurn(
      startCodingAgentTurn({
        harness: "codex",
        sessionId: "still-open",
        turnId: "turn-1",
        prompt: "Keep this chat open",
        startedAt: "2026-08-19T10:00:00.000Z",
      }),
      {
        response: "The turn is still complete.",
        endedAt: "2026-08-19T10:00:01.000Z",
      },
    );

    expect(completed.status).toBe("completed");
    expect(codingAgentTurnTrace(completed).endedAt).toBe(
      "2026-08-19T10:00:01.000Z",
    );
  });

  it("makes duplicate completion idempotent and rejects late tools", () => {
    const completed = completeCodingAgentTurn(
      startCodingAgentTurn({
        harness: "codex",
        sessionId: "session-1",
        turnId: "turn-1",
        prompt: "hello",
        startedAt: "2026-08-19T10:00:00.000Z",
      }),
      {
        response: "first",
        endedAt: "2026-08-19T10:00:01.000Z",
      },
    );

    expect(
      completeCodingAgentTurn(completed, {
        response: "ignored duplicate",
        endedAt: "2026-08-19T10:00:02.000Z",
      }),
    ).toBe(completed);
    expect(() =>
      recordCodingAgentToolStart(completed, {
        toolUseId: "late",
        toolName: "exec_command",
        input: {},
        startedAt: "2026-08-19T10:00:02.000Z",
      }),
    ).toThrow("already completed");
  });

  it("records a post-tool event even when the pre-tool event was missed", () => {
    const open = recordCodingAgentToolResult(
      startCodingAgentTurn({
        harness: "codex",
        sessionId: "session-1",
        turnId: "turn-1",
        prompt: "hello",
        startedAt: "2026-08-19T10:00:00.000Z",
      }),
      {
        toolUseId: "tool-1",
        toolName: "read_file",
        input: { path: "README.md" },
        error: "permission denied",
        endedAt: "2026-08-19T10:00:01.000Z",
      },
    );

    expect(open.tools).toEqual([
      expect.objectContaining({
        toolUseId: "tool-1",
        toolName: "read_file",
        input: { path: "README.md" },
        error: "permission denied",
        endedAt: "2026-08-19T10:00:01.000Z",
        startTimeMissing: true,
      }),
    ]);
  });

  it("merges a delayed start into a result-only tool", () => {
    const resultOnly = recordCodingAgentToolResult(
      startCodingAgentTurn({
        harness: "codex",
        sessionId: "session-1",
        turnId: "turn-1",
        prompt: "hello",
        startedAt: "2026-08-19T10:00:00.000Z",
      }),
      {
        toolUseId: "tool-1",
        toolName: "read_file",
        output: "contents",
        endedAt: "2026-08-19T10:00:02.000Z",
      },
    );

    const merged = recordCodingAgentToolStart(resultOnly, {
      toolUseId: "tool-1",
      toolName: "read_file",
      input: { path: "README.md" },
      startedAt: "2026-08-19T10:00:01.000Z",
    });

    expect(merged.tools).toEqual([
      expect.objectContaining({
        toolUseId: "tool-1",
        input: { path: "README.md" },
        output: "contents",
        startedAt: "2026-08-19T10:00:01.000Z",
        endedAt: "2026-08-19T10:00:02.000Z",
        startTimeMissing: undefined,
      }),
    ]);
  });

  it("marks missing tool telemetry without inventing an execution failure", async () => {
    const completed = completeCodingAgentTurn(
      recordCodingAgentToolStart(
        startCodingAgentTurn({
          harness: "codex",
          sessionId: "session-1",
          turnId: "turn-1",
          prompt: "run a tool",
          startedAt: "2026-08-19T10:00:00.000Z",
        }),
        {
          toolUseId: "tool-1",
          toolName: "exec_command",
          startedAt: "2026-08-19T10:00:01.000Z",
        },
      ),
      {
        response: "The tool result was lost.",
        endedAt: "2026-08-19T10:00:02.000Z",
      },
    );
    const fetchMock = vi.fn(async () => new Response("{}", { status: 201 }));
    const lemma = new Lemma({
      apiKey: "scoped-key",
      projectId: "10000000-0000-0000-0000-000000000001",
      baseUrl: "https://api.example.test",
      fetch: fetchMock as typeof fetch,
    });

    const assembled = codingAgentTurnTrace(completed);
    await lemma.ingest(assembled.context, {
      startedAt: new Date(assembled.startedAt),
      endedAt: new Date(assembled.endedAt),
    });

    expect(completed.tools[0]).toMatchObject({
      resultMissing: true,
    });
    expect(jsonBody(fetchMock.mock.calls[0]).trace.spans[0]).toMatchObject({
      metadata: {
        tool_use_id: "tool-1",
        result_missing: true,
      },
    });
    expect(jsonBody(fetchMock.mock.calls[0]).trace.spans[0]).not.toHaveProperty(
      "ended_at",
    );
    expect(jsonBody(fetchMock.mock.calls[0]).trace.spans[0]).not.toHaveProperty(
      "status",
    );
    expect(jsonBody(fetchMock.mock.calls[0]).trace.spans[0].error).toBeNull();
  });

  it("emits the assistant generation without inventing unavailable timing", async () => {
    const completed = completeCodingAgentTurn(
      startCodingAgentTurn({
        harness: "codex",
        sessionId: "session-1",
        turnId: "turn-1",
        prompt: "hello",
        startedAt: "2026-08-19T10:00:00.000Z",
        model: "gpt-5",
      }),
      {
        response: "done",
        endedAt: "2026-08-19T10:00:02.000Z",
      },
    );
    const fetchMock = vi.fn(async () => new Response("{}", { status: 201 }));
    const lemma = new Lemma({
      apiKey: "scoped-key",
      projectId: "10000000-0000-0000-0000-000000000001",
      baseUrl: "https://api.example.test",
      fetch: fetchMock as typeof fetch,
    });

    const assembled = codingAgentTurnTrace(completed);
    await lemma.ingest(assembled.context, {
      startedAt: new Date(assembled.startedAt),
      endedAt: new Date(assembled.endedAt),
    });

    expect(jsonBody(fetchMock.mock.calls[0]).trace.spans).toEqual([
      expect.objectContaining({
        id: completed.generationId,
        type: "generation",
        model: "gpt-5",
        input: "hello",
        output: "done",
        metadata: { timing_missing: true },
      }),
    ]);
    expect(jsonBody(fetchMock.mock.calls[0]).trace.spans[0]).not.toHaveProperty(
      "started_at",
    );
    expect(jsonBody(fetchMock.mock.calls[0]).trace.spans[0]).not.toHaveProperty(
      "ended_at",
    );
  });

  it("treats a null tool error as success and marks missing starts", async () => {
    const completed = completeCodingAgentTurn(
      recordCodingAgentToolResult(
        startCodingAgentTurn({
          harness: "codex",
          sessionId: "session-1",
          turnId: "turn-1",
          prompt: "read a file",
          startedAt: "2026-08-19T10:00:00.000Z",
        }),
        {
          toolUseId: "tool-1",
          toolName: "read_file",
          error: null,
          endedAt: "2026-08-19T10:00:01.000Z",
        },
      ),
      {
        response: "Done.",
        endedAt: "2026-08-19T10:00:02.000Z",
      },
    );
    const fetchMock = vi.fn(async () => new Response("{}", { status: 201 }));
    const lemma = new Lemma({
      apiKey: "scoped-key",
      projectId: "10000000-0000-0000-0000-000000000001",
      baseUrl: "https://api.example.test",
      fetch: fetchMock as typeof fetch,
    });

    const assembled = codingAgentTurnTrace(completed);
    await lemma.ingest(assembled.context, {
      startedAt: new Date(assembled.startedAt),
      endedAt: new Date(assembled.endedAt),
    });

    expect(jsonBody(fetchMock.mock.calls[0]).trace.spans[0]).toMatchObject({
      status: "OK",
      ended_at: "2026-08-19T10:00:01.000Z",
      metadata: {
        tool_use_id: "tool-1",
        start_time_missing: true,
      },
    });
    expect(jsonBody(fetchMock.mock.calls[0]).trace.spans[0]).not.toHaveProperty(
      "started_at",
    );
  });

  it("preserves an explicit null tool input", () => {
    const open = recordCodingAgentToolResult(
      startCodingAgentTurn({
        harness: "codex",
        sessionId: "session-1",
        turnId: "turn-1",
        prompt: "run a no-argument tool",
        startedAt: "2026-08-19T10:00:00.000Z",
      }),
      {
        toolUseId: "tool-1",
        toolName: "refresh",
        input: null,
        output: "done",
        endedAt: "2026-08-19T10:00:01.000Z",
      },
    );

    expect(open.tools[0].input).toBeNull();
  });

  it("normalizes Error objects before turns are persisted", () => {
    const open = recordCodingAgentToolResult(
      startCodingAgentTurn({
        harness: "codex",
        sessionId: "session-1",
        turnId: "turn-1",
        prompt: "read a file",
        startedAt: "2026-08-19T10:00:00.000Z",
      }),
      {
        toolUseId: "tool-1",
        toolName: "read_file",
        error: new TypeError("permission denied"),
        endedAt: "2026-08-19T10:00:01.000Z",
      },
    );

    expect(open.tools[0].error).toBe("TypeError: permission denied");
    expect(JSON.parse(JSON.stringify(open))).toMatchObject({
      tools: [{ error: "TypeError: permission denied" }],
    });
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { jsonBody } from "../test-helpers";
import { disableDebugMode, enableDebugMode } from "./debug-mode";
import { openAIAgents } from "./openai-agents";

describe("openAIAgents", () => {
  beforeEach(() => {
    disableDebugMode();
  });

  afterEach(() => {
    disableDebugMode();
    vi.restoreAllMocks();
  });

  it("records OpenAI Agents generation and function spans under one trace", async () => {
    const fetchMock = vi.fn(async () => new Response("{}", { status: 201 }));
    const processor = openAIAgents({
      apiKey: "key",
      projectId: "10000000-0000-0000-0000-000000000001",
      fetch: fetchMock as typeof fetch,
    });

    await processor.onTraceStart({
      traceId: "trace_openai_1",
      name: "support-agent",
      groupId: "thread-1",
      metadata: { userId: "user-1" },
    });
    await processor.onSpanStart({
      traceId: "trace_openai_1",
      spanId: "span_generation_1",
      spanData: {
        type: "generation",
        input: [{ role: "user", content: "where is my order?" }],
        model: "gpt-4o",
        model_config: { temperature: 0.2 },
      },
